 2. Fázis: Sparse Műveletek (Taco)

c
// mi355x_sparse.c (Taco generated)
#include "taco.h"

// Define sparse tensor format for MI355X
typedef struct {
    int* row_ptr;
    int* col_idx;
    float* values;
    int num_rows;
    int nnz;
} CSR_MI355X;

// Taco DSL definition
Tensor<float> spmv_mi355x() {
    Tensor<float> A("A", {M, N}, Format({Dense, Sparse})); // CSR
    Tensor<float> x("x", {N}, Format({Dense}));
    Tensor<float> y("y", {M}, Format({Dense}));

    IndexVar i, j;
    y(i) = A(i,j) * x(j);

    // Compile for MI355X
    y.compile(Compile::ROCm, {
        .target = "gfx942",
        .wave_size = 64,
        .use_infinity_cache = true,
        .vectorization = 16
    });

    return y;
}


 3. Fázis: MultiGPU Koordináció (Regent)

lua
-- mi355x_distributed.rg
import "regent"

-- Define field space for MI355X tensor
fspace TensorField {
  data : float,
  grad : float
}

-- Partitioning strategy for 8x MI355X setup
task partition_tensor_8gpu(
  r : region(ispace(int2d), TensorField),
  colors : ispace(int1d)
)
  var p = partition(equal, r, colors) -- Equal partition
  return p
end

-- Multi-GPU training step
task training_step_mi355x(
  weights : region(ispace(int2d), TensorField),
  inputs : region(ispace(int2d), TensorField),
  p_weights : partition(disjoint, weights),
  p_inputs : partition(disjoint, inputs)
)
where reads writes(weights, inputs) do
  -- Legion automatikusan kezel 8x MI355X-et
  __demand(__cuda, __hip)
  for color in p_weights.colors do
    -- Minden GPU saját régióját dolgozza fel
    forward_pass(p_weights[color], p_inputs[color])
  end

  -- AllReduce gradiens szinkronizáció
  -- Legion optimalizálja az Infinity Fabric-et használva
  __demand(__hip_aware_mpi)
  for color in p_weights.colors do
    allreduce_gradients(p_weights[color])
  end
end

