pub const DataFlowAnalyzer = struct {
    access_patterns: AutoHashMap(u64, ArrayList(usize)),
    flow_graph: AutoHashMap(u64, ArrayList(u64)),
    allocator: Allocator,

    pub fn init(allocator: Allocator) DataFlowAnalyzer {
        return .{
            .access_patterns = AutoHashMap(u64, ArrayList(usize)).init(allocator),
            .flow_graph = AutoHashMap(u64, ArrayList(u64)).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *DataFlowAnalyzer) void {
        var it = self.access_patterns.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.access_patterns.deinit();

        var it2 = self.flow_graph.iterator();
        while (it2.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.flow_graph.deinit();
    }

    pub fn recordAccess(self: *DataFlowAnalyzer, block_id: u64, core_id: usize) !void {
        const result = try self.access_patterns.getOrPut(block_id);
        if (!result.found_existing) {
            result.value_ptr.* = ArrayList(usize).init(self.allocator);
        }
        try result.value_ptr.append(core_id);
    }

    pub fn addDataFlow(self: *DataFlowAnalyzer, from: u64, to: u64) !void {
        const result = try self.flow_graph.getOrPut(from);
        if (!result.found_existing) {
            result.value_ptr.* = ArrayList(u64).init(self.allocator);
        }
        try result.value_ptr.append(to);
    }

    pub fn getMostFrequentCore(self: *DataFlowAnalyzer, block_id: u64) ?usize {
        if (self.access_patterns.get(block_id)) |accesses| {
            if (accesses.items.len == 0) return null;

            var counts = AutoHashMap(usize, usize).init(self.allocator);
            defer counts.deinit();

            for (accesses.items) |core_id| {
                const result = counts.getOrPut(core_id) catch continue;
                if (!result.found_existing) {
                    result.value_ptr.* = 0;
                }
                result.value_ptr.* += 1;
            }

            var max_core: usize = 0;
            var max_count: usize = 0;
            var it = counts.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.* > max_count) {
                    max_count = entry.value_ptr.*;
                    max_core = entry.key_ptr.*;
                }
            }

            return if (max_count > 0) max_core else null;
        }
        return null;
    }
};

pub const DynamicTaskScheduler = struct {
    task_queue: ArrayList(TaskDescriptor),
    task_map: AutoHashMap(u64, usize),
    next_task_id: u64,
    allocator: Allocator,

    pub fn init(allocator: Allocator) DynamicTaskScheduler {
        return .{
            .task_queue = ArrayList(TaskDescriptor).init(allocator),
            .task_map = AutoHashMap(u64, usize).init(allocator),
            .next_task_id = 1,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *DynamicTaskScheduler) void {
        for (self.task_queue.items) |*task| {
            task.deinit();
        }
        self.task_queue.deinit();
        self.task_map.deinit();
    }

    pub fn submitTask(self: *DynamicTaskScheduler, priority: u32) !u64 {
        const id = self.next_task_id;
        self.next_task_id += 1;

        var task = TaskDescriptor.init(self.allocator, id, priority);
        try self.task_queue.append(task);
        try self.task_map.put(id, self.task_queue.items.len - 1);

        return id;
    }

    pub fn scheduleToCore(self: *DynamicTaskScheduler, cores: []ProcessingCore, analyzer: *DataFlowAnalyzer) !?u64 {
        if (self.task_queue.items.len == 0) return null;

        var best_idx: usize = 0;
        var best_priority: u32 = self.task_queue.items[0].priority;

        for (self.task_queue.items, 0..) |task, i| {
            if (task.priority > best_priority) {
                best_priority = task.priority;
                best_idx = i;
            }
        }

        const task = self.task_queue.orderedRemove(best_idx);
        _ = self.task_map.remove(task.id);

        var best_core_idx: usize = 0;
        var min_load: f32 = cores[0].load;

        for (cores, 0..) |core, i| {
            if (core.load < min_load) {
                min_load = core.load;
                best_core_idx = i;
            }
        }

        cores[best_core_idx].load += task.computation_weight;
        try cores[best_core_idx].processing_queue.append(task.id);

        return task.id;
    }
};

pub const ChaosCoreKernel = struct {
    storage: ContentAddressableStorage,
    cores: ArrayList(ProcessingCore),
    scheduler: DynamicTaskScheduler,
    analyzer: DataFlowAnalyzer,
    config: ChaosCoreConfig,
    cycle_count: u64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, num_cores: usize, config: ChaosCoreConfig) !ChaosCoreKernel {
        var cores = ArrayList(ProcessingCore).init(allocator);
        for (0..num_cores) |i| {
            try cores.append(ProcessingCore.init(allocator, i));
        }

        return ChaosCoreKernel{
            .storage = ContentAddressableStorage.init(allocator, 1024 * 1024 * 100),
            .cores = cores,
            .scheduler = DynamicTaskScheduler.init(allocator),
            .analyzer = DataFlowAnalyzer.init(allocator),
            .config = config,
            .cycle_count = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ChaosCoreKernel) void {
        self.storage.deinit();
        for (self.cores.items) |*core| {
            core.deinit();
        }
        self.cores.deinit();
        self.scheduler.deinit();
        self.analyzer.deinit();
    }

    pub fn executeCycle(self: *ChaosCoreKernel) !void {
        _ = try self.scheduler.scheduleToCore(self.cores.items, &self.analyzer);

        for (self.cores.items) |*core| {
            if (core.processing_queue.items.len > 0) {
                const task_id = core.processing_queue.orderedRemove(0);
                _ = task_id;
                core.load = @max(0.0, core.load - 0.1);
            }
        }

        if (self.cycle_count % 100 == 0) {
            try self.balanceLoad();
        }

        self.cycle_count += 1;
    }

    fn balanceLoad(self: *ChaosCoreKernel) !void {
        var total_load: f32 = 0.0;
        for (self.cores.items) |core| {
            total_load += core.load;
        }
        const avg_load = total_load / @as(f32, @floatFromInt(self.cores.items.len));
        _ = avg_load;
    }

    pub fn storeData(self: *ChaosCoreKernel, data: []const u8) !u64 {
        return self.storage.store(data);
    }

    pub fn retrieveData(self: *ChaosCoreKernel, id: u64) ?[]const u8 {
        return self.storage.retrieve(id);
    }
};

