pub const RelationalTriplet = struct {
    subject: []const u8,
    relation: []const u8,
    object: []const u8,
    confidence: f32,
    source_hash: [32]u8,
    metadata: StringHashMap([]const u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator, subject: []const u8, relation: []const u8, object: []const u8, confidence: f32) !RelationalTriplet {
        var metadata = StringHashMap([]const u8).init(allocator);
        var hash: [32]u8 = undefined;

        const combined = try std.fmt.allocPrint(allocator, "{s}|{s}|{s}", .{subject, relation, object});
        defer allocator.free(combined);
        std.crypto.hash.blake3.hash(combined, &hash, .{});

        return RelationalTriplet{
            .subject = try allocator.dupe(u8, subject),
            .relation = try allocator.dupe(u8, relation),
            .object = try allocator.dupe(u8, object),
            .confidence = confidence,
            .source_hash = hash,
            .metadata = metadata,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *RelationalTriplet) void {
        self.allocator.free(self.subject);
        self.allocator.free(self.relation);
        self.allocator.free(self.object);

        var it = self.metadata.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.metadata.deinit();
    }

    pub fn toGraphElements(self: *const RelationalTriplet, graph: *nsir_core.SelfSimilarRelationalGraph) !void {
        try graph.addNode(self.subject, null);
        try graph.addNode(self.object, null);
        try graph.addEdge(self.subject, self.object, self.confidence);
    }
};

