            .subject_index = StringHashMap(ArrayList(usize)).init(allocator),
            .relation_index = StringHashMap(ArrayList(usize)).init(allocator),
            .object_index = StringHashMap(ArrayList(usize)).init(allocator),
            .triplets = ArrayList(RelationalTriplet).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *KnowledgeGraphIndex) void {
        var it1 = self.subject_index.iterator();
        while (it1.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.subject_index.deinit();

        var it2 = self.relation_index.iterator();
        while (it2.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.relation_index.deinit();

        var it3 = self.object_index.iterator();
        while (it3.next()) |entry| {
            entry.value_ptr.deinit();
