        }
        try result2.value_ptr.append(idx);

        const result3 = try self.object_index.getOrPut(triplet.object);
        if (!result3.found_existing) {
            result3.value_ptr.* = ArrayList(usize).init(self.allocator);
        }
        try result3.value_ptr.append(idx);
