pub const StreamBuffer = struct {
    buffer: []RelationalTriplet,
    capacity: usize,
    head: usize,
    tail: usize,
    count: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, capacity: usize) !StreamBuffer {
        const buffer = try allocator.alloc(RelationalTriplet, capacity);
        return StreamBuffer{
            .buffer = buffer,
            .capacity = capacity,
            .head = 0,
            .tail = 0,
            .count = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StreamBuffer) void {
        for (0..self.count) |i| {
            const idx = (self.head + i) % self.capacity;
            self.buffer[idx].deinit();
        }
        self.allocator.free(self.buffer);
    }

    pub fn push(self: *StreamBuffer, triplet: RelationalTriplet) !void {
        if (self.count >= self.capacity) {
            self.buffer[self.head].deinit();
            self.head = (self.head + 1) % self.capacity;
            self.count -= 1;
        }

        self.buffer[self.tail] = triplet;
        self.tail = (self.tail + 1) % self.capacity;
        self.count += 1;
    }

    pub fn pop(self: *StreamBuffer) ?RelationalTriplet {
        if (self.count == 0) return null;

        const triplet = self.buffer[self.head];
        self.head = (self.head + 1) % self.capacity;
        self.count -= 1;
        return triplet;
    }
};

